-- ============================================================================
-- BMS — Default seed data for a newly provisioned tenant database
-- ============================================================================
-- Generated 2026-08-31 (multi-tenancy Phase 2). Applied by
-- core/tenant_provisioner.php immediately after schema/tenant_schema_template.sql.
--
-- WHAT IS IN HERE, and why each table earns its place:
--   account_types, account_categories  accounting taxonomy (generic)
--   accounts                           chart of accounts, STRUCTURAL ONLY
--   permissions                        the application's permission catalogue
--   roles, role_permissions            so the owner account has working access
--
-- WHAT IS DELIBERATELY NOT IN HERE:
--   users            every tenant's owner is created fresh by the provisioner.
--   system_settings  mixes platform defaults with company identity AND secrets
--                    (e.g. the encrypted AI API key). Copying it would hand one
--                    tenant's credentials to every later signup.
--   Sub-ledger accounts (is_subledger = 1). In the source database 90 of the 195
--                    accounts are per-customer/per-supplier sub-ledgers carrying
--                    REAL COUNTERPARTY NAMES. Seeding them would leak Tenant #1's
--                    customer list into every new tenant. Only the 105 structural
--                    accounts are included; they form a self-contained tree with
--                    no dangling parent_account_id.
--   Any transactional table — journal_entries, invoices, payments, and the rest
--                    stay empty. A new tenant starts with a zero ledger.
--
-- REGENERATING: see docs/MULTI_TENANCY_CONVENTIONS.md §8. Re-verify the
-- exclusions above before committing a regenerated file — the sub-ledger filter
-- is the one that matters most.
-- ============================================================================

SET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;



-- ── Sanitisation ────────────────────────────────────────────────────────────
-- Belt-and-braces: a fresh tenant's ledger must start at zero no matter what
-- balances existed in the source database when this file was generated. Twelve
-- accounts carried non-zero balances at generation time. This runs regardless,
-- so a future regeneration cannot silently reintroduce them.
UPDATE `accounts` SET `opening_balance` = 0.00, `current_balance` = 0.00;

-- Defensive: if a regeneration ever forgets the is_subledger filter, drop them
-- here rather than leaking counterparty names into a new tenant.
DELETE FROM `accounts` WHERE `is_subledger` = 1;

SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;
